package plymeld.commands

import java.nio.file.Files
import java.nio.file.Path
import java.time.LocalDate
import java.time.ZoneId

/**
 * Which plymeld made a g-code file, and when, as the readings sheets record it: the version from the file's header line
 * (`; generated by plymeld VERSION`, docs/gcode-format.md) and the date the file was last written. The header carries no
 * date, so the same version, models, and values give the same file.
 */
internal object MadeBy {
    private val GENERATED = Regex("""^; generated by (plymeld \S+)$""")

    /** The date [file] was last written, in this computer's time zone. */
    fun dateOf(file: Path): LocalDate = Files.getLastModifiedTime(file).toInstant().atZone(ZoneId.systemDefault()).toLocalDate()

    /** "plymeld VERSION on DATE" (without the date when [written] is null); null when the first ten [lines] hold no header line. */
    fun text(lines: List<String>, written: LocalDate?): String? {
        val version = lines.take(10).firstNotNullOfOrNull { GENERATED.find(it) }?.groupValues?.get(1) ?: return null
        return if (written == null) version else "$version on $written"
    }
}
